CREATE TABLE IF NOT EXISTS pastoral_imports (id TEXT PRIMARY KEY, source_name TEXT NOT NULL, source_sha256 TEXT NOT NULL UNIQUE, imported_at TEXT NOT NULL, response_count INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS pastoral_responses (import_id TEXT NOT NULL REFERENCES pastoral_imports(id), source_row INTEGER NOT NULL, submitted_at TEXT, payload TEXT NOT NULL CHECK(json_valid(payload)), PRIMARY KEY(import_id,source_row));
CREATE TABLE IF NOT EXISTS pastoral_profiles (person_id TEXT PRIMARY KEY REFERENCES directory_records(id), role TEXT NOT NULL CHECK(role IN ('pastor','pastora')), rut TEXT, fecha_nacimiento TEXT CHECK(fecha_nacimiento IS NULL OR fecha_nacimiento GLOB '[0-9][0-9][0-9][0-9]-[0-9][0-9]-[0-9][0-9]'), telefono TEXT, correo_contacto TEXT, estado_civil TEXT, domicilio_particular TEXT, fecha_matrimonio TEXT, fecha_nombramiento TEXT, source_import TEXT REFERENCES pastoral_imports(id), source_row INTEGER, submitted_at TEXT, updated_at TEXT NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS pastoral_rut_unique ON pastoral_profiles(rut) WHERE rut IS NOT NULL AND rut <> '';
CREATE INDEX IF NOT EXISTS pastoral_birthdays_idx ON pastoral_profiles(substr(fecha_nacimiento,6));
CREATE TABLE IF NOT EXISTS pastoral_assignments (import_id TEXT NOT NULL REFERENCES pastoral_imports(id), source_row INTEGER NOT NULL, church_id TEXT NOT NULL REFERENCES directory_records(id), pastor_id TEXT NOT NULL REFERENCES directory_records(id), pastora_id TEXT REFERENCES directory_records(id), submitted_at TEXT NOT NULL, direccion TEXT NOT NULL, horarios_texto TEXT NOT NULL, zona TEXT NOT NULL, needs_review INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(import_id,source_row));
CREATE VIEW IF NOT EXISTS pastoral_birthdays AS SELECT p.person_id,p.role,p.fecha_nacimiento,substr(p.fecha_nacimiento,6) AS mes_dia,json_extract(d.draft,'$.nombre') AS nombre FROM pastoral_profiles p JOIN directory_records d ON d.id=p.person_id;
CREATE TABLE IF NOT EXISTS site_data (id TEXT PRIMARY KEY, data TEXT NOT NULL CHECK(json_valid(data)), updated_at TEXT NOT NULL);
